def raw_exercise():
    L = ['مشق', '', '۱۔ مختصر جوابات دیں:']
    L += [f'({r}) {q}' for r, (q, _) in zip(['i', 'ii', 'iii', 'iv', 'v', 'vi', 'vii', 'viii'], QS)]
    L += ['', '۲۔ جملے مکمل کریں:']
    L += [f'({h}) {s}' for h, (s, _) in zip(['الف', 'ب', 'ج', 'د', 'ہ', 'و', 'ز', 'ح'], BLANKS)]
    L += ['', '۳۔ سیاق و سباق کے حوالے سے کسی عبارت کی وضاحت کرنی ہو، تو تین سرخیاں دیں:'] + Q3_GUIDE
    L += ['اب آپ سیاق و سباق کے حوالے سے مندرجہ ذیل اقتباس کی وضاحت کریں۔', f'"{PASSAGE}"']
    L += ['', '۴۔ مندرجہ ذیل الفاظ کے مترادف لکھیں۔', 'متانت، مجلس، میوہ، ارشاد، بہشت، دام۔']
    L += ['', '۵۔ ' + Q5_INTRO, 'مثلاً: (ا) فواد نیک ہے۔ (ب) عدنان لکھتا ہے۔',
          'ان مثالوں میں فواد اور عدنان مسندالیہ ہیں۔ "نیک ہے" اور "لکھتا ہے" مسند ہیں۔ آپ مندرجہ ذیل جملوں میں مسندالیہ اور مسند کی پہچان کریں:']
    L += [f'{n}۔ {s}' for n, s, _, _ in GRAMMAR_SENT]
    L += ['', ACTIVITY, '', 'ہدایات برائے اساتذہ:'] + TEACHER
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['blanks'] = [dict(statement=s, answer=a) for s, a in BLANKS]
    g = ex['grammar'][0]
    g['topic'] = 'اسناد، مسند اور مسندالیہ کی پہچان'
    g['explanation'] = Q5_INTRO
    g['practiceSentences'] = [dict(num=n, sentence=s, musnadIlaih=mi, musnad=m) for n, s, mi, m in GRAMMAR_SENT]
    g.pop('additionalDocxExamples', None)
    g.pop('sampleExamples', None)
    g['examples'] = ['فواد نیک ہے۔ (مسندالیہ: فواد، مسند: نیک ہے)', 'عدنان لکھتا ہے۔ (مسندالیہ: عدنان، مسند: لکھتا ہے)']
    t = ex['contextualTashreeh']
    t['guidelines'] = dict(title='سیاق و سباق کے حوالے سے وضاحت کی تین سرخیاں:', heading1=Q3_GUIDE[0], heading2=Q3_GUIDE[1], heading3=Q3_GUIDE[2])
    t['passage'] = PASSAGE
    t['reference'] = f'سبق: اخلاقِ نبوی {S} · مصنف: مولانا شبلی نعمانی · ماخوذ از: سیرۃ النبی {S} (جلد دوم)'
    t['context'] = (f'یہ اقتباس مولانا شبلی نعمانی کے مضمون "اخلاقِ نبوی {S}" کے حصے "حسنِ خلق" سے لیا گیا ہے۔ اس سے پہلے مصنف بتاتے ہیں کہ آپ '
                    'ملاقات کے وقت خود پہلے سلام کرتے، لوگوں کی ناگوار باتیں برداشت فرماتے اور زعفران لگا کر آنے والے صاحب کو ان کے سامنے کچھ نہ کہا۔ اس کے بعد مصنف آپ کے ایثار کا ذکر کرتے ہیں۔')
